function handler(event) {
  var request = event.request;
  var qs = request.querystring;
  var keep = ['page', 'lang'];
  var clean = {};
  keep.forEach(function (k) {
    if (qs[k]) { clean[k] = { value: qs[k].value.toLowerCase() }; }
  });
  request.querystring = clean;
  return request;
}

